<script lang="ts">
    interface Props { page: number; pages: number; href: (page: number) => string; }
    let { page, pages, href }: Props = $props();
    const adjacent = $derived(Array.from({ length: Math.max(0, Math.min(pages, 5)) }, (_, index) => Math.min(Math.max(1, page - 2) + index, pages)));
</script>
{#if pages > 1}<nav class="flex flex-wrap gap-2" aria-label="Pagination"><a class={`min-w-10 rounded-lg border border-wg-border px-3 py-[0.55rem] text-center text-sm font-semibold text-wg-text no-underline ${page === 1 ? "pointer-events-none opacity-45" : ""}`} aria-disabled={page === 1} href={href(Math.max(1, page - 1))}>Previous</a>{#each adjacent as current}<a class={`min-w-10 rounded-lg border px-3 py-[0.55rem] text-center text-sm font-semibold no-underline ${current === page ? "border-wg-accent bg-wg-accent text-wg-accent-contrast" : "border-wg-border text-wg-text"}`} aria-current={current === page ? "page" : undefined} href={href(current)}>{current}</a>{/each}<a class={`min-w-10 rounded-lg border border-wg-border px-3 py-[0.55rem] text-center text-sm font-semibold text-wg-text no-underline ${page === pages ? "pointer-events-none opacity-45" : ""}`} aria-disabled={page === pages} href={href(Math.min(pages, page + 1))}>Next</a></nav>{/if}
